from django.db import migrations

# Every tagulous tag table. Their models are generated by tagulous at runtime, so the index is
# created with SQL only: declaring it in the migration state would make makemigrations emit a
# RemoveIndex for each table, since the generated models declare no indexes.
TAG_TABLES = (
    "dojo_tagulous_app_analysis_tags",
    "dojo_tagulous_endpoint_inherited_tags",
    "dojo_tagulous_endpoint_tags",
    "dojo_tagulous_engagement_inherited_tags",
    "dojo_tagulous_engagement_tags",
    "dojo_tagulous_finding_inherited_tags",
    "dojo_tagulous_finding_tags",
    "dojo_tagulous_finding_template_tags",
    "dojo_tagulous_location_inherited_tags",
    "dojo_tagulous_location_tags",
    "dojo_tagulous_objects_product_tags",
    "dojo_tagulous_product_tags",
    "dojo_tagulous_test_inherited_tags",
    "dojo_tagulous_test_tags",
)


def index_name(table):
    return "idx_" + table.removeprefix("dojo_") + "_upper_name"


def add_indexes(apps, schema_editor):
    connection = schema_editor.connection
    if connection.vendor != "postgresql":
        return
    # CONCURRENTLY cannot run in a transaction block; a caller's transaction (a test, a tenant
    # migrated under an outer atomic block) gets a plain build.
    concurrently = "" if connection.in_atomic_block else "CONCURRENTLY "
    with connection.cursor() as cursor:
        for table in TAG_TABLES:
            name = index_name(table)
            # An interrupted CONCURRENTLY build leaves an INVALID index that IF NOT EXISTS would keep.
            cursor.execute(
                "SELECT indisvalid FROM pg_index WHERE indexrelid = to_regclass(%s)",
                [name],
            )
            row = cursor.fetchone()
            if row is not None and not row[0]:
                cursor.execute(f'DROP INDEX {concurrently}IF EXISTS "{name}"')
            cursor.execute(
                f'CREATE INDEX {concurrently}IF NOT EXISTS "{name}" '
                f'ON "{table}" (UPPER("name"::text) text_pattern_ops)',
            )
            # Statistics for the new expression, so the planner can estimate a lookup on it.
            cursor.execute(f'ANALYZE "{table}"')


def remove_indexes(apps, schema_editor):
    connection = schema_editor.connection
    if connection.vendor != "postgresql":
        return
    concurrently = "" if connection.in_atomic_block else "CONCURRENTLY "
    with connection.cursor() as cursor:
        for table in TAG_TABLES:
            cursor.execute(f'DROP INDEX {concurrently}IF EXISTS "{index_name(table)}"')


class Migration(migrations.Migration):

    """
    Index UPPER(name) on every tag table.

    Tag fields are case-insensitive, so tagulous finds each tag it adds with
    get_or_create(name__iexact=...), which compiles to UPPER("name"::text) = UPPER(%s). The unique
    index on name cannot serve that, so every tag added to an object read the whole tag table. On an
    instance whose pipelines create, tag and delete findings all the time, tag rows pile up (a tag is
    not deleted when its last finding is), and a finding PATCH that set 12 tags spent 18 s reading a
    3,000,000-row tag table twelve times. The importer, the bulk tag helpers and tag search
    (istartswith, which text_pattern_ops also serves) use the same expression. Non-atomic so each
    index can build CONCURRENTLY without blocking tag writes; safe to re-run.
    """

    atomic = False

    dependencies = [
        ("dojo", "0307_event_history_lookup_indexes"),
    ]

    operations = [
        migrations.RunPython(add_indexes, remove_indexes),
    ]
